import { getBaseUrl } from '@skyramp/skyramp';

const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

export async function addProductToCart(page) {
    await page.getByRole("button", { name: "Add To Cart" }).click();
}

export async function selectProductQuantity(page, quantity) {
    await page.locator("#quantity").selectOption(quantity);
}

export async function submitCartQuantityUpdate(page, productId, quantity) {
    return await page.request.post(`${baseUrl}/cart/update`, {
        form: { product_id: productId, quantity: quantity },
        maxRedirects: 0,
    });
}

export async function incrementCartQuantity(page) {
    await page.locator(".qty-control button.qty-inc").click();
}
